import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百一十四章 穿着漂亮法衣的难陀尊者","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/214第二百一十四章 穿着漂亮法衣的难陀尊者.md","filePath":"meditation/巴利文大藏经/214第二百一十四章 穿着漂亮法衣的难陀尊者.md"}'),o={name:"meditation/巴利文大藏经/214第二百一十四章 穿着漂亮法衣的难陀尊者.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百一十四章-穿着漂亮法衣的难陀尊者" tabindex="-1">第二百一十四章 穿着漂亮法衣的难陀尊者 <a class="header-anchor" href="#第二百一十四章-穿着漂亮法衣的难陀尊者" aria-label="Permalink to &quot;第二百一十四章 穿着漂亮法衣的难陀尊者&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部21相应8经/难陀经(比丘相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，难陀尊者穿着崭新漂亮的法衣，打扮的光鲜亮丽，拿着黄金打造的饭钵，来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，佛陀对难陀尊者说：“难陀！对于一个出家人来说，穿着崭新漂亮的法衣，打扮的光鲜亮丽，拿着黄金饭钵，这是不合适的。你出家修行的目的是为了熄灭内心的欲望，而不是增加内心的贪欲。一个出家人如果是在山林野地、简陋的地方居住修行，是拿着普通的饭钵中午的时候到乡村或城镇中挨家挨户、不分贫富贵贱的家庭化缘饭食，是穿着世间人不要的衣服、布料裁剪而成的法衣，那就是合适的，因为他们不会因为居住的环境，穿着的衣服，吃饭的器物而生起执着和挂念，他们这样去修行能够熄灭内心的贪欲，不会对世间任何的事物有所期待，不会沉浸在欲望的海洋之中，能除灭一切的烦恼和痛苦。他们能够将自己的内心安住在清净的境界之中，难陀，你也应该这样的去修行。</p><p>难陀什么时候如来才能看见你在山林野地、简陋的地方居住修行呢？什么时候如来才能看见你穿上世间人不要的衣服、布料裁剪而成的法衣呢？什么时候如来才能看见你拿着普通的饭钵中午的时候到乡村或城镇中挨家挨户、不分贫富贵贱的家庭化缘饭食呢？什么时候如来才能看见你对世间任何的事物都不再有所期待，才能看见你熄灭内心的贪欲，不再沉浸在欲望的海洋之中呢？”</p><p>这时，佛陀说偈言：</p><p>「何日见难陀，</p><p>粪扫衣住林。</p><p>支身依遗穗，</p><p>希见无欲事。」</p><p>佛陀说法后，难陀尊者惭愧的低下了头，他再次的顶礼佛陀，在佛陀的面前虔诚的忏悔。他随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p><p>难陀尊者来到僧团里的法衣裁剪处，脱下了自己崭新漂亮的法衣，穿上了用世间人不要的衣服、布料裁剪而成的法衣。他离开了华丽高大的宅院，来到了密林里。他住在了自己搭建的简陋茅草棚中，他将黄金饭钵变卖后，将所得的钱财全部都送给了城镇里面的穷苦人家。他每天中午穿上破旧的法衣，拿着一个普通的饭钵到城镇里挨家挨户、不分贫富贵贱的家庭化缘饭食，他不再打扮自己。难陀尊者遵循佛陀的教导逐渐熄灭了自己内心的贪欲，他不再为居住的环境、衣服、饭食、装饭食的器物等等世间的事物束缚捆绑，他无欲无求，他不再执着和挂念世间的事物，安住在清净的境界之中。</p>',12)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
